const requirements=[
 ['01','Borradores sin bloqueos','12973280385','La cotización Tramp/TBN no debe depender de una nave completa en el maestro.','Guardar con datos parciales; validar al aprobar solo datos aplicables. GRT y eslora se exigen si intervienen en el cálculo.','Comercial + Agenciamiento: confirmar mínimos y si una PDA provisional puede aprobarse.','Reunión del viernes; correo de César','general'],
 ['02','Roles marítimos y datos de nave','12973280385','Armador, cliente y pagador no siempre son la misma entidad.','Separar cliente, facturar a, head owner, charterer y technical manager. Cambios de particulares solo en esta PDA; alta definitiva controlada.','Confirmar facturación por cuenta de terceros y dueño del maestro.','Transcripción: roles / nave TBN','general'],
 ['03','Cliente provisional','13040783048','Un cliente extranjero no registrado bloquea una cotización.','Buscar por nombre; si no existe, capturar datos provisionales sin crear un maestro.','Validar razón social, dirección, contacto y correo como mínimos de formalización.','Transcripción: creación rápida','general'],
 ['04','Fórmulas y conceptos de plantillas','13023081897','Conceptos faltantes y resultados distintos en plantilla, PDA y PDF.','Motor compartido; navegación = tarifa × TRG × cantidad; amarradero = tarifa × eslora × horas. Agregar carga/descarga, llenos/vacíos y conceptos aplicables por terminal.','Facturación debe validar unidad, tarifa, vigencia y aplicabilidad de cada concepto; los valores no son un tarifario aprobado.','Reunión, PDF PDA35, pantalla observada y correo César','services'],
 ['05','IGV visible y consistente','13023081897','PDF sin discriminación del IGV por concepto ni totales; comisión ambigua.','Seleccionar pendiente, gravado sin IGV, gravado con IGV incluido, exonerado o inafecto. Separar base e impuesto; bloquear aprobación con impuestos sin definir.','Confirmar tratamiento tributario por concepto y si USD 413 incluye IGV. El 18% es un escenario, no una determinación tributaria.','Correo César + reunión','services'],
 ['06','PDF bilingüe y alineado','12973296249','“DISBUSEMENT”, mezcla de idiomas, números desalineados y hoja de remarks vacía.','DISBURSEMENT; documento completo ES/EN; importes alineados, dos decimales, sin “celular”, comentarios solo si existen.','Validar diseño y traducciones con César; información bancaria se omite en esta simulación.','PDF PDA2026000035PECLL y correo César','document'],
 ['07','Descarga antes del envío','12973269738','Se requiere revisar la PDA antes de enviarla.','Vista previa e impresión disponibles en borrador, sin cambiar estado. Envío simulado separado de aprobación.','Confirmar permisos y marca de agua para documentos preliminares.','Ticket Comercial existente','document'],
 ['08','Guardado seguro de plantilla','12973346018','Error interno al guardar plantilla (UAT002/UAT004).','Validación específica, preservación de edición y versiones locales. Solo una versión publicada debe usarse en producción.','La causa del error real no se corrige con este mockup; requiere prueba técnica de guardado/reintento.','Ticket Comercial existente','templates'],
 ['09','Validación de proveedor y provisiones','12973269745','Servicio validado sin proveedor no genera provisión.','Proveedor obligatorio únicamente al validar el servicio operativo; nunca para guardar el borrador comercial.','Facturación: confirmar mapeo y generación de provisión real, no implementada aquí.','Ticket Comercial existente','providers'],
 ['10','Filtros operativos','13040781818','Ya existen filtros de nave, cliente, puerto, estado, ETA/ETD.','Conservarlos y añadir viaje, tipo de servicio y creador; distinguir fecha de creación, ETA y ETD.','Confirmar filtros mínimos y permisos de visualización.','Pantalla observada + reunión','list'],
 ['11','Recargos trazables','13040760706','Reglas por horario, feriado, eslora y dos prácticas aún ambiguas.','Registro manual con base, porcentaje, causa y proveedor. Sin automatismos de horario; historial local.','Validar porcentajes, horarios, feriados, acumulación y aprobación. Ejemplos 30/50/100% de la reunión NO se activan automáticamente.','Transcripción: recargos','surcharges'],
 ['12','Terminales y gobierno de catálogos','13023081897','Faltan puertos, terminales y tipos de carga.','Mostrar dependencia de Datos Maestros; usar catálogo demostrativo, sin altas silenciosas.','Validar catálogo oficial Callao/Paracas y demás terminales; no dar la lista del mockup por completa.','Reunión: dependencia de Datos Maestros','templates']
];
function sample(){return {id:'PDA2026000035PECLL',vessel:'BOX ENDURANCE',vesselMode:'Registrada',type:'Portacontenedores',voyage:'684',grt:21667,loa:171.98,tonnage:0,flag:'Liberia',imo:'9733820',captain:'',client:'ZIM INTEGRATED SHIPPING SERVICE LTD',billTo:'ZIM INTEGRATED SHIPPING SERVICE LTD',clientMode:'Registrado',owner:'',charterer:'',broker:'',manager:'',settlementTo:'',address:'',contact:'',email:'',currency:'USD',exchange:3.36,payment:'Por definir',service:'Liner',agency:'Agente Marítimo',operation:'Importación / Exportación',cargo:'Contenerizada',port:'Callao',terminal:'DP World Callao S.R.L.',lastPort:'Savannah',eta:'2026-09-10T00:00',etd:'2026-09-11T00:00',remarksEs:'',remarksEn:'',status:'Creada',sent:false,confirmed:false,created:'2026-09-09',creator:'Comercial',template:'Callao · Liner · versión de propuesta 1'};}
function sampleRows(){return [
 ['agency','Comisión de agencia','Agency fee',413,1,'Servicio'],
 ['port','Uso de amarradero','Berth occupancy',1.5,10,'LOA × horas'],
 ['port','Practicaje · exportación','Pilotage · departure',1200,2,'Servicio'],
 ['port','Lancha · servicio continuado','Launch · continuous service',150,4,'Hora'],
 ['port','Remolcaje','Towage',145.97,4,'Servicio'],
 ['port','Despacho','Clearance',150,1,'Servicio'],
 ['authority','Recepción','Vessel reception',0,0,'Servicio'],
 ['authority','Ayudas a la navegación','Navigation aids',.03,1,'TRG × cantidad']
 ].map((r,i)=>({id:i+1,group:r[0],es:r[1],en:r[2],rate:r[3],qty:r[4],unit:r[5],tax:'pending',enabled:true,provider:'',validated:false,source:'PDF recibido',reason:''}));}
let pda=sample(),rows=sampleRows(),history=[{at:'Referencia · 14/09/2026',text:'Propuesta iniciada desde PDF PDA35 y observación del sistema. No es una modificación de la PDA real.'}],versions=[],decisions={};
let mode='proposed',page='detail',tab='general',lang='es',filter={},savedExists=false;
try{const stored=JSON.parse(localStorage.getItem('cosmos-pda-mockup-v1')||'null');if(stored?.pda&&Array.isArray(stored.rows)){({pda,rows,history,versions,decisions}=stored);savedExists=true;}}catch{}
const groups={agency:['Comisión de agencia y otros servicios','Agency fees and other services'],port:['Gastos portuarios','Port expenses'],authority:['Autoridades marítimas','Maritime authorities'],cargo:['Operaciones de carga','Cargo operations'],surcharge:['Recargos operativos','Operational surcharges']};
const taxNames={pending:'Por validar',excluded:'Gravado · +18%',included:'Gravado · incluye 18%',exempt:'Exonerado',unaffected:'Inafecto'};
const logo=()=>`<div class="logo" aria-label="Cosmos Global Logistics"><span class="brandmark"><img src="cosmos_logotipo_azul1_fondo_transparente.png" alt="Cosmos Global Logistics"></span></div>`;
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const option=(v,cur,label=v)=>`<option value="${esc(v)}" ${v===cur?'selected':''}>${esc(label)}</option>`;
function field(label,key,type='text',opts=null,help=''){const val=pda[key]??'';return `<label class="field">${label}${opts?`<select data-field="${key}" ${mode==='actual'?'disabled':''}>${opts.map(x=>option(x,val)).join('')}</select>`:`<input data-field="${key}" type="${type}" value="${esc(val)}" ${type==='number'?'min="0" step="any"':''} ${mode==='actual'?'disabled':''}>`}${help?`<span class="help">${help}</span>`:''}</label>`;}
function log(text){history.unshift({at:new Date().toLocaleString('es-PE'),text});}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function store(){try{localStorage.setItem('cosmos-pda-mockup-v1',JSON.stringify({pda,rows,history,versions,decisions}));savedExists=true;return true;}catch{toast('No se pudo guardar en este navegador. Mantén esta pestaña abierta.');return false;}}
function changed(text){pda.confirmed=false;pda.sent=false;if(pda.status==='Aprobada')pda.status='Creada';log(text);}
function shell(){return `<header><div class="top">${logo()}<span class="branch muted">⌖ &nbsp; Callao⌄</span><span class="spacer"></span><span class="date muted">Lunes 14 de septiembre de 2026</span><span>🇵🇪</span><div class="avatar">AP</div></div><nav><span>◉ Dashboard</span><div class="navdrop">${btn('▱ &nbsp; PDA ⌄','menu','navactive')}<div id="navmenu" class="navmenu" hidden>${btn('PDA','list')}${btn('PDA Plantilla','templates')}</div></div><span>◇ Agenciamiento ⌄</span><span>◈ Tarifa</span><span>▤ Documentación ⌄</span><span>Atención al cliente</span><span>Liquidación</span><span>Tesorería</span><span>Data Maestra</span></nav></header><div class="studio"><b>LABORATORIO COMERCIAL</b><div class="seg">${btn('Actual · referencia','actual',mode==='actual'?'on':'')}${btn('Propuesta','proposed',mode==='proposed'?'on':'')}</div><span>Mockup local · sin conexión de escritura al sistema</span><span class="spacer"></span>${btn('12 cambios y validaciones ↗','review','review')}</div><main class="workspace">${content()}</main>`;}
function render(){document.documentElement.lang='es';$('#app').innerHTML=shell();if(page==='detail'&&mode==='proposed'&&tab!=='document'){const f=$('.footerbar');f?.insertAdjacentHTML('beforeend',btn('Cargar ejemplo PDA35','load-sample'));}}
function content(){if(page==='review')return review();if(page==='list')return listing();if(page==='templates')return templates();return detail();}
function crumb(title){return `<div class="crumb">${btn('←','list','small','aria-label="Volver al listado"')} Inicio <span>/</span> PDA <span>/</span> ${title}</div>`;}
function detail(){const actual=mode==='actual';const states=['Anulada','Aprobada','Borrador','Completada','Creada','En Ajuste','En Viaje','Rechazada','Validada'];return `${crumb(actual?'Ver PDA':'Editar propuesta')}<div class="heading"><div><div class="kicker">${actual?'REFERENCIA OBSERVADA · SOLO LECTURA':'COMERCIAL / PDA · PROPUESTA DE DEFINICIÓN'}</div><h1>${actual?'PDA2026000035PECLL':esc(pda.id)}</h1>${actual?`<div class="statusflow" aria-label="Estados de la PDA">${states.map(s=>`<span class="badge ${s==='En Viaje'?'green':''}">${s}</span>`).join('')}</div>`:`<span class="tagline">${esc(pda.vessel||'Nave por definir')} · ${esc(pda.service)} · ${esc(pda.port||'Puerto por definir')}</span> &nbsp;<span class="badge blue">${esc(pda.status)}${pda.status==='Creada'?' · borrador':''}</span> <span class="badge">${pda.sent?'Envío simulado':'No enviada'}</span>`}</div><span class="spacer"></span><div class="actions">${btn('Historial','history')}${actual?btn('Duplicar','reference-duplicate'):''}${!actual?btn('Vista previa','document'):''}${!actual?btn('Guardar borrador','save','primary'):''}</div></div>${actual?`<div class="notice actualnote">Esta réplica cubre las pantallas observadas de la PDA35, no todo el portal. Pantalla: USD 4,811.89; PDF recibido: USD 6,726.61. Son dos evidencias distintas; no se ha verificado que correspondan a la misma versión.</div>`:`<div class="notice"><span>ⓘ</span><div><b>Propuesta para validar con Comercial, Agenciamiento y Facturación.</b> Puedes guardar datos incompletos. Las tarifas vienen del PDF; fórmulas, impuestos y mandatorios deben confirmarse antes de aprobación. Todo se guarda solo en este navegador.<br><span class="help"><b>(*)</b> obligatorio al aprobar; sin (*) es opcional o referencial en el borrador.</span></div></div>`}<div class="tabs">${(actual?[['general','Información General'],['services','Detalle'],['document','PDF recibido']]:[['general','Información general'],['services','Servicios y cálculos'],['surcharges','Recargos'],['document','Documento'],['providers','Validación operativa'],['history','Historial']]).map(([id,t])=>btn(t,'tab',tab===id?'active':'',`data-tab="${id}"`)).join('')}</div>${actual?actualContentFixed():({general:general,services:services,surcharges:surcharges,document:documentView,providers:providers,history:timeline}[tab]||general)()}${!actual&&tab!=='document'?`<div class="footerbar"><span class="muted">${pda.template?esc(pda.template):'Sin plantilla aplicada'}<br><small>Una edición posterior invalida la aprobación simulada.</small></span><span class="spacer"></span>${btn('Nueva PDA / TBN','new')}${btn('Revisar para aprobar','approve','primary')}</div>`:''}`;}
function general(){return `<div class="grid3"><section class="card"><div class="cardhead"><span class="ico">♧</span><h2>Datos del buque</h2></div>${field('Origen de la nave','vesselMode','text',['Registrada','Provisional / TBN'])}${field('Nave o referencia provisional (*)','vessel','text',null,'(*) obligatorio al aprobar; puedes escribir TBN o una nave nueva. No se da de alta en el maestro.')}${field('Tipo de nave','type','text',['Portacontenedores','Granelero','Tanque','Por definir'])}<div class="grid2">${field('Viaje / referencia (*)','voyage')}${field('TRG / GRT (si aplica)','grt','number',null,'Obligatorio solo si la plantilla o tarifa lo utiliza.')}</div><div class="grid2">${field('Eslora / LOA (si aplica)','loa','number',null,'Obligatoria solo si la plantilla o tarifa lo utiliza.')}${field('Tonelaje de carga (t)','tonnage','number')}</div><div class="grid2">${field('Bandera','flag')}${field('IMO / Lloyd','imo')}</div>${field('Nombre del Capitán (opcional)','captain')}${field('Email del Capitán (opcional)','email','email')}<p class="formbottom">Particulares editables solo para esta cotización. La homologación definitiva pertenece al responsable de Datos Maestros.</p></section><section class="card"><div class="cardhead"><span class="ico">♙</span><h2>Cliente / Facturación</h2></div>${field('Cliente solicitante (*)','client','text',null,'(*) debe existir un cliente facturable confirmado al aprobar.')}<div class="actions" style="margin:-7px 0 19px">${btn('Buscar / alta provisional','client','small')}<span class="badge ${pda.clientMode==='Provisional'?'amber':''}">${esc(pda.clientMode)}</span></div>${field('Facturar por cuenta de (*)','billTo','text',null,'(*) pagador/disponent confirmado al aprobar; no se asigna automáticamente al propietario.')}<div class="grid2">${field('Head owner (opcional)','owner')}${field('Charterer / disponent (opcional)','charterer')}</div>${field('Broker (opcional)','broker')}${field('Technical manager (opcional)','manager')}${field('Enviar liquidación a (opcional)','settlementTo')}<div class="grid2">${field('Moneda (*)','currency','text',['USD'])}${field('Tipo de cambio referencial (*)','exchange','number',null,'(*) positivo al aprobar; tarifas de ejemplo expresadas en USD.')}</div>${field('Condición de pago','payment','text',['Por definir','Contado','Crédito 30 días'])}<p class="formbottom">Validar roles, pagador y eventual facturación por servicio. No se genera un registro en SAF ni un comprobante.</p></section><section class="card"><div class="cardhead"><span class="ico">⚙</span><h2>Configuración operativa</h2></div><div class="grid2">${field('Tipo de servicio (*)','service','text',['Liner','Tramp'])}${field('Agenciamiento (*)','agency','text',['Agente Marítimo','Agente Protector'])}</div>${field('Operación (*)','operation','text',['Importación / Exportación','Importación','Exportación','Otros'])}${field('Tipo de carga (*)','cargo','text',['Contenerizada','Granel sólido','Granel líquido','Carga general','Por definir'])}<div class="grid2">${field('Puerto (*)','port','text',['Callao','Paracas','Por definir'])}${field('Terminal (*)','terminal','text',['DP World Callao S.R.L.','Terminal Portuario Paracas','Por definir'])}</div><span class="help">Catálogo de demostración. Faltantes: dependencia de Datos Maestros.</span><div class="grid2">${field('ETA (*) · fecha y hora local','eta','datetime-local')}${field('ETD (*) · fecha y hora local','etd','datetime-local')}</div>${field('Último puerto (referencial)','lastPort')}<label class="field">Observaciones para documento ES<textarea data-field="remarksEs">${esc(pda.remarksEs)}</textarea></label><label class="field">Observaciones para documento EN<textarea data-field="remarksEn" placeholder="Traducción validada por el usuario">${esc(pda.remarksEn)}</textarea></label></section></div>`;}
function servicesFixed(){const t=E.totals(rows,pda);return `<div class="bar"><div><h2>Conceptos y base de cálculo</h2><span class="muted">Tarifas del PDF recibido · cambia valores para comparar escenarios</span></div><span class="spacer"></span>${btn('PDA Plantilla','templates')}${btn('+ Agregar concepto','add-service','primary')}</div><div class="notice warn">${t.pending} concepto(s) pendiente(s) de tarifa, base o impuesto. “Por validar” muestra la base sin calcular IGV: el total es provisional, no un monto a cobrar. Un importe cero no acredita que el concepto no aplique.</div><div class="tablewrap"><table><thead><tr><th>Usar</th><th>Concepto / origen</th><th>Tarifa Unitaria</th><th>Tarifa</th><th>Moneda</th><th>Cantidad</th><th>A/E</th><th>Tratamiento IGV</th><th class="num">Base neta</th><th class="num">IGV</th><th class="num">Total</th><th>Comentarios</th><th>Val. Ope.</th><th></th></tr></thead><tbody>${Object.entries(groups).map(([g,names])=>{const rr=rows.filter(r=>r.group===g);if(!rr.length)return '';return `<tr class="group"><td colspan="14">${names[0]} <span class="badge">${rr.length}</span></td></tr>`+rr.map(r=>{const v=E.calc(r,pda);return `<tr><td><input aria-label="Incluir ${esc(r.es)}" type="checkbox" data-row="${r.id}" data-key="enabled" ${r.enabled?'checked':''}></td><td><div class="service">${esc(r.es)}</div><small>${esc(r.source)}</small>${v.missing?'<span class="help" style="color:#ae6500">Completar tarifa o base</span>':''}</td><td><select aria-label="Tarifa unitaria ${esc(r.es)}" data-row="${r.id}" data-key="unit">${['Servicio','Hora','Contenedor','LOA × horas','TRG × cantidad'].map(x=>option(x,r.unit)).join('')}</select><span class="help">${r.unit==='LOA × horas'?`× ${esc(pda.loa||'?')} m`:r.unit==='TRG × cantidad'?`× ${esc(pda.grt||'?')} TRG`:'Tarifa × cantidad'}</span></td><td><input aria-label="Tarifa ${esc(r.es)}" type="number" min="0" step="any" data-row="${r.id}" data-key="rate" value="${r.rate}"></td><td>USD</td><td><input aria-label="Cantidad ${esc(r.es)}" type="number" min="0" step="any" data-row="${r.id}" data-key="qty" value="${r.qty}"></td><td>—</td><td><select aria-label="IGV ${esc(r.es)}" data-row="${r.id}" data-key="tax">${Object.entries(taxNames).map(([k,v])=>option(k,r.tax,v)).join('')}</select></td><td class="num">${money(v.net)}</td><td class="num">${r.tax==='pending'&&r.enabled?'—':money(v.tax)}</td><td class="num"><b>${money(v.total)}</b></td><td>${r.reason?esc(r.reason):'—'}</td><td>${r.provider?(r.validated?'Validado':'Pendiente'):'—'}</td><td>${btn('Ajuste','adjust','small',`data-id="${r.id}"`)}</td></tr>`;}).join('');}).join('')}</tbody></table></div>${metrics(t)}<div class="notice" style="margin-top:20px">Ayudas a la navegación: 0.03 × 21,667 × 1 = <b>650.01</b>. Amarradero: 1.50 × 171.98 × 10 = <b>2,579.70</b>. Son ejemplos de corrección de fórmula a validar, no tarifas aprobadas. El mismo cálculo alimenta el documento.</div>`;}
function metrics(t){return `<div class="totalcards"><div class="metric"><small>BASE NETA · USD</small><strong>${money(t.net)}</strong></div><div class="metric"><small>IGV CALCULADO · USD</small><strong>${money(t.tax)}</strong></div><div class="metric"><small>CONCEPTOS PENDIENTES</small><strong>${t.pending}</strong></div><div class="metric main"><small>TOTAL ${t.pending?'PROVISIONAL':'DEL ESCENARIO'} · USD</small><strong>${money(t.total)}</strong></div></div>`;}
