function actualDetailReference(){const meta={agency:['Comisión de agencia y otros servicios',413],port:['Gastos portuarios',3748.88],authority:['Gastos por autoridades marítimas',650.01]};const order=['agency','port','authority'];const rr=actualRowsReference();const body=order.map(g=>{const list=rr.filter(r=>r.group===g);return `<tr class="group"><td colspan="10">${meta[g][0]} <span class="badge">${list.length}</span></td></tr>${list.map(r=>`<tr><td>${esc(r.es)}</td><td>${esc(r.unit)}</td><td class="num">${money(r.rate)}</td><td>${esc(r.currency)}</td><td class="num">${r.qty}</td><td>${esc(r.ae)}</td><td>${esc(r.vat)}</td><td class="num"><b>${money(r.total)}</b></td><td>${r.comments?esc(r.comments):'—'}</td><td>${r.ope?esc(r.ope):'—'}</td></tr>`).join('')}<tr class="actual-subtotal"><td colspan="7" class="num"><b>Subtotal</b></td><td class="num"><b>${money(meta[g][1])}</b></td><td colspan="2"></td></tr>`;}).join('');return `<div class="tablewrap"><table class="actualtable"><thead><tr><th>Servicio</th><th>Tarifa Unitaria</th><th class="num">Tarifa</th><th>Moneda</th><th class="num">Cantidad</th><th>A/E</th><th>VAT</th><th class="num">Total</th><th>Comentarios</th><th>Val. Ope.</th></tr></thead><tbody>${body}</tbody></table></div><div class="actual-category-summary"><div class="kicker">RESUMEN POR CATEGORÍA</div>${order.map(g=>`<div class="summary-line"><span>${meta[g][0]}</span><b>USD ${money(meta[g][1])}</b></div>`).join('')}</div><div class="actual-total"><div><span>Agency</span><b>USD 413.00</b></div><div><span>Port expenses</span><b>USD 3,748.88</b></div><div><span>Maritime authorities</span><b>USD 650.01</b></div><div><span>VAT</span><b>USD 0.00</b></div><div class="grand"><span>TOTAL</span><span>USD 4,811.89</span></div></div>`;}
function actualContentFixed(){if(tab==='document')return `<div class="notice actualnote">Primera página del PDF proporcionado, sin modificaciones. El original tiene una segunda página de remarks vacía.</div><img class="originalimg" src="original-pda.png" alt="Primera página del PDF original PDA2026000035PECLL">`;if(tab==='history')return `<div class="card">La réplica no inventa el historial del sistema. Consulta la propuesta para ver los eventos de esta simulación.</div>`;if(tab==='services')return actualDetailReference();const prior=pda;pda=sample();pda.loa=171;pda.exchange=3;pda.type='Portacontenedores';pda.billTo='';pda.broker='';pda.settlementTo='';const html=`<div class="grid3"><section class="card"><h2>Datos del Buque</h2>${field('Nave','vessel')}${field('Tipo Nave','type')}${field('Viaje','voyage')}${field('TRG','grt')}${field('Eslora · valor visible','loa')}${field('Tonelaje','tonnage')}${field('País','flag')}${field('Lloyd','imo')}${field('Nombre del Capitán','captain')}${field('Email del Capitán','email')}</section><section class="card"><h2>Cliente / Facturación</h2>${field('Armador','client')}${field('Cliente','client')}${field('Broker','broker')}${field('Facturar por cuenta de','billTo')}${field('Enviar liquidación a','settlementTo')}${field('Moneda','currency')}${field('Tipo Cambio · valor visible','exchange')}${field('Condición Pago','payment')}${field('Head Owner','owner')}${field('Charterer','charterer')}</section><section class="card"><h2>Configuración Operativa</h2>${field('Tipo Servicio','service')}${field('Tipo Agenciamiento','agency')}${field('Tipo Operación','operation')}${field('Carga','cargo')}${field('Puerto','port')}${field('Terminal','terminal')}${field('Último Puerto','lastPort')}${field('ETA','eta')}${field('ETD','etd')}</section></div>`;pda=prior;return html;}
function listing(){const data=[{...sample(),status:'En Viaje',source:'Referencia observada'},{...pda,source:'Propuesta local',id:pda.id+(pda.id===sample().id?' · propuesta':'')}];const records=data.filter(d=>(!filter.q||[d.id,d.vessel,d.voyage,d.client].join(' ').toLowerCase().includes(filter.q.toLowerCase()))&&(!filter.state||d.status===filter.state)&&(!filter.service||d.service===filter.service)&&(!filter.creator||d.creator===filter.creator)&&(!filter.port||d.port===filter.port)&&(!filter.from||(d[filter.dateType||'eta']||'').slice(0,10)>=filter.from)&&(!filter.to||(d[filter.dateType||'eta']||'').slice(0,10)<=filter.to));return `${crumb('Buscar PDA')}<div class="heading"><div><div class="kicker">COMERCIAL</div><h1>Buscar PDA</h1><span class="muted">Busca, revisa y continúa tus cotizaciones.</span></div><span class="spacer"></span>${btn('+ Nueva PDA','new','primary')}</div><section class="card"><div class="filters"><label class="field">Código, nave, viaje o cliente<input data-filter="q" value="${esc(filter.q||'')}" placeholder="Ej. BOX ENDURANCE"></label><label class="field">Estado<select data-filter="state">${['','Creada','En Viaje','Aprobada','Rechazada','Anulada'].map(x=>option(x,filter.state||'',x||'Todos')).join('')}</select></label><label class="field">Tipo de servicio<select data-filter="service">${['','Liner','Tramp'].map(x=>option(x,filter.service||'',x||'Todos')).join('')}</select></label><label class="field">Puerto<select data-filter="port">${['','Callao','Paracas'].map(x=>option(x,filter.port||'',x||'Todos')).join('')}</select></label><label class="field">Fecha a consultar<select data-filter="dateType">${[['eta','ETA'],['etd','ETD'],['created','Fecha de creación']].map(([k,v])=>option(k,filter.dateType||'eta',v)).join('')}</select></label><label class="field">Desde<input data-filter="from" type="date" value="${esc(filter.from||'')}"></label><label class="field">Hasta<input data-filter="to" type="date" value="${esc(filter.to||'')}"></label><label class="field">Creador<select data-filter="creator">${option('',filter.creator||'','Todos')}${option('Comercial',filter.creator||'')}</select></label></div><div class="actions">${btn('Buscar','search','primary')}${btn('Limpiar','clear-search')}</div></section><div class="bar" style="margin-top:25px"><h2 style="margin:0">Resultados <span class="badge">${records.length}</span></h2><span class="spacer"></span><small>2 escenarios locales · no es el listado completo de Monday/Cosmos</small></div><div class="tablewrap"><table><thead><tr><th>Código PDA / origen</th><th>Nave</th><th>Viaje</th><th>ETA</th><th>Puerto</th><th>Cliente</th><th>Estado</th></tr></thead><tbody>${records.map(d=>`<tr><td>${btn(esc(d.id),'open-record','linkbtn',`data-origin="${d.source}"`)}<span class="help">${d.source}</span></td><td>${esc(d.vessel||'TBN')}</td><td>${esc(d.voyage||'—')}</td><td>${esc((d.eta||'').replace('T',' '))}</td><td>${esc(d.port)}</td><td class="longname">${esc(d.client||'Por definir')}</td><td><span class="badge blue">${esc(d.status)}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Sin resultados para estos filtros.</td></tr>'}</tbody></table></div>`;}
function documentView(){const en=lang==='en', t=E.totals(rows,pda),tr=(a,b)=>en?b:a;const tx={pending:['Pendiente','Pending'],excluded:['Gravado 18%','Taxable 18%'],included:['Incluido 18%','Included 18%'],exempt:['Exonerado','Exempt'],unaffected:['Inafecto','Not subject']};const unitName=u=>en?({'Servicio':'Service','Hora':'Hour','Contenedor':'Container','LOA × horas':'LOA × hours','TRG × cantidad':'GRT × quantity'}[u]||'Service'):u;const val=(k)=>esc(pda[k]||tr('Por definir','To be defined'));const displayDate=v=>v?new Date(v).toLocaleString(en?'en-GB':'es-PE',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):tr('Por definir','To be defined');const translateValue=(v)=>en?({'Portacontenedores':'Container ship','Granelero':'Bulk carrier','Tanque':'Tanker','Por definir':'To be defined','Contenerizada':'Containerized','Granel sólido':'Dry bulk','Granel líquido':'Liquid bulk','Carga general':'General cargo','Contado':'Cash','Crédito 30 días':'30-day credit','Servicio':'Service'}[v]||v):v;return `<div class="doccontrols"><label for="doclang">Idioma del documento</label><select id="doclang" data-language>${option('es',lang,'Español')}${option('en',lang,'English')}</select><span class="spacer"></span>${btn('Imprimir / guardar PDF','print','primary')}${btn('Simular envío','send')}</div><div class="docscroll"><article class="paper" lang="${lang}"><div class="paperhead">${logo()}<div class="num"><b>${esc(pda.id)}</b><div class="help">${tr('SIMULACIÓN · NO VÁLIDA PARA COBRO','SIMULATION · NOT VALID FOR PAYMENT')}</div></div></div><h1>${tr('CUENTA PROFORMA DE DESEMBOLSOS (PDA)','PROFORMA DISBURSEMENT ACCOUNT (PDA)')}</h1><div class="notice warn" style="font-size:10px">${tr('Documento preliminar. Tratamiento tributario, tarifas y fórmulas sujetos a validación.','Preliminary document. Tax treatment, rates and formulas are subject to validation.')} ${t.pending?tr(`${t.pending} conceptos pendientes.`,`${t.pending} pending items.`):''}</div><div class="docmeta"><div><span>${tr('Cliente','Client')}</span><b>${val('client')}</b></div><div><span>${tr('Fecha de emisión','Issue date')}</span><b>${tr('14 sep 2026','14 Sep 2026')}</b></div><div><span>${tr('Facturar a','Bill to')}</span><b>${val('billTo')}</b></div><div><span>${tr('Moneda','Currency')}</span><b>USD</b></div><div><span>${tr('Nave / viaje','Vessel / voyage')}</span><b>${val('vessel')} / ${val('voyage')}</b></div><div><span>${tr('Tipo de nave','Vessel type')}</span><b>${esc(translateValue(pda.type))}</b></div><div><span>${tr('Puerto / terminal','Port / terminal')}</span><b>${val('port')} / ${val('terminal')}</b></div><div><span>GRT / LOA</span><b>${Number(pda.grt).toLocaleString('en-US')} / ${money(pda.loa)} m</b></div><div><span>ETA / ETD</span><b>${displayDate(pda.eta)} / ${displayDate(pda.etd)}</b></div><div><span>${tr('Carga','Cargo')}</span><b>${esc(translateValue(pda.cargo))}</b></div><div><span>${tr('Tipo de cambio','Exchange rate')}</span><b>${money(pda.exchange)}</b></div><div><span>${tr('Condición de pago','Payment terms')}</span><b>${esc(translateValue(pda.payment))}</b></div></div><table><thead><tr><th>${tr('Concepto','Service')}</th><th>${tr('Unidad / base','Unit / basis')}</th><th class="num">${tr('Tarifa','Rate')}</th><th class="num">${tr('Cant.','Qty.')}</th><th>${tr('Impuesto','Tax')}</th><th class="num">${tr('Neto','Net')}</th><th class="num">${tr('IGV','VAT')}</th><th class="num">${tr('Total','Total')} USD</th></tr></thead><tbody>${Object.entries(groups).map(([g,n])=>{const list=rows.filter(r=>r.enabled&&r.group===g);if(!list.length)return '';return `<tr class="group"><td colspan="8">${n[en?1:0]}</td></tr>`+list.map(r=>{const v=E.calc(r,pda);return `<tr><td>${esc(en?r.en:r.es)}</td><td>${unitName(r.unit)}${r.unit==='LOA × horas'?` · ${money(pda.loa)}`:r.unit==='TRG × cantidad'?` · ${Number(pda.grt).toLocaleString('en-US')}`:''}</td><td class="num">${r.rate===''?'—':money(r.rate)}</td><td class="num">${r.qty}</td><td>${tx[r.tax][en?1:0]}</td><td class="num">${v.missing?'—':money(v.net)}</td><td class="num">${r.tax==='pending'?'—':money(v.tax)}</td><td class="num">${v.missing?'—':money(v.total)}</td></tr>`;}).join('')+`<tr><td colspan="5" class="num"><b>${tr('Subtotal','Subtotal')}</b></td><td class="num">${money(E.totals(list,pda).net)}</td><td class="num">${money(E.totals(list,pda).tax)}</td><td class="num"><b>${money(E.totals(list,pda).total)}</b></td></tr>`;}).join('')}</tbody></table><div class="docbottom"><div style="font-size:11px;line-height:1.8"><b>Cosmos Global Logistics S.A.C.</b><br>${tr('Datos bancarios omitidos en esta simulación.','Bank details omitted in this simulation.')}<br>${tr('No realizar transferencias con este documento.','Do not make transfers using this document.')}</div><div class="docsum"><div><span>${tr('Base gravada','Taxable net')}</span><b>${money(E.totals(rows.filter(r=>['included','excluded'].includes(r.tax)),pda).net)}</b></div><div><span>${tr('Exonerado / inafecto','Exempt / not subject')}</span><b>${money(E.totals(rows.filter(r=>['exempt','unaffected'].includes(r.tax)),pda).net)}</b></div><div><span>${tr('Base pendiente de clasificación','Net pending classification')}</span><b>${money(E.totals(rows.filter(r=>r.tax==='pending'),pda).net)}</b></div><div><span>${tr('Total neto','Net total')}</span><b>${money(t.net)}</b></div><div><span>${tr('IGV calculado (18%)','Calculated VAT (18%)')}</span><b>${money(t.tax)}</b></div><div class="grand"><span>${tr('Total provisional','Provisional total')}</span><span>USD ${money(t.total)}</span></div></div></div>${(en?pda.remarksEn:pda.remarksEs)?`<div class="footnote"><b>${tr('OBSERVACIONES','REMARKS')}</b><p>${esc(en?pda.remarksEn:pda.remarksEs).replace(/\n/g,'<br>')}</p></div>`:''}${en&&pda.remarksEs&&!pda.remarksEn?'<div class="footnote">Remarks translation pending. English document is incomplete; do not send.</div>':''}<div class="footnote">${tr('Documento generado con la misma base de cálculo de la pantalla. Valores de ejemplo para validación funcional, no tarifas ni impuestos aprobados.','Document generated from the same calculation model as the screen. Sample values for functional validation, not approved rates or tax treatment.')}</div></article></div>`;}
function surcharges(){return `<div class="twocol"><section class="card"><div class="kicker">FASE 1 · REGISTRO MANUAL</div><h2>Recargos operativos con sustento</h2><p class="muted">El horario de la nave no aplica recargos automáticamente. Registra el porcentaje acordado y el servicio base; quedará como un concepto independiente.</p><div class="grid2"><label class="field">Servicio base<select id="s-base">${rows.filter(r=>r.enabled&&r.group!=='surcharge').map(r=>`<option value="${r.id}">${esc(r.es)}</option>`).join('')}</select></label><label class="field">Porcentaje acordado<input id="s-percent" type="number" min="0" max="1000" placeholder="Ej. 30"></label><label class="field">Causa / sustento<input id="s-reason" placeholder="Horario, feriado, condición contractual…"></label><label class="field">Proveedor / fuente<input id="s-provider" placeholder="Identificación de la fuente"></label></div>${btn('+ Incorporar recargo','add-surcharge','primary')}<p class="help">Base neta congelada al registrar; si cambia el servicio original debes revisar el recargo. Impuesto independiente pendiente de clasificar.</p></section><aside class="card"><span class="badge amber">Por validar con el usuario</span><h2 style="margin-top:17px">Antes de automatizar</h2><p>Facturación debe confirmar horarios, calendario de feriados, porcentajes, eslora, dos prácticas y reglas de acumulación.</p><p class="muted">Los ejemplos de 30%, 50% y 100% de la reunión no se consideran una regla aprobada.</p>${btn('Ver ticket y decisiones','review')}</aside></div><div class="card" style="margin-top:20px"><h2>Recargos de esta PDA</h2>${rows.filter(r=>r.group==='surcharge').map(r=>`<p><b>${esc(r.es)}</b> · USD ${money(r.rate)}<br><small>${esc(r.reason)}</small></p>`).join('')||'<p class="muted">Aún no hay recargos registrados.</p>'}</div>`;}
function providers(){return `<div class="notice warn">El proveedor es obligatorio al validar el servicio operativo, no al crear ni guardar la PDA. Esta pantalla solo simula la regla; no crea provisiones reales.</div><div class="tablewrap"><table><thead><tr><th>Servicio</th><th>Proveedor</th><th>Validación</th><th>Provisión</th></tr></thead><tbody>${rows.filter(r=>r.enabled).map(r=>`<tr><td>${esc(r.es)}</td><td><input aria-label="Proveedor ${esc(r.es)}" data-row="${r.id}" data-key="provider" value="${esc(r.provider)}" placeholder="Proveedor requerido al validar"></td><td>${btn(r.validated?'Quitar validación':'Validar servicio','validate-service',r.validated?'small':'primary small',`data-id="${r.id}"`)}</td><td><span class="badge ${r.validated?'green':'amber'}">${r.validated?'Elegible · simulación':'No validado'}</span></td></tr>`).join('')}</tbody></table></div>`;}
function templates(){return `${crumb('PDA Plantilla')}<div class="heading"><div><div class="kicker">CONFIGURACIÓN COMERCIAL</div><h1>PDA Plantilla</h1><span class="muted">Base por terminal y servicio · ajustes independientes en cada PDA</span></div><span class="spacer"></span>${btn('Volver a PDA','back-detail','primary')}</div><div class="notice warn">Catálogo y tarifas demostrativos. Guardar crea una versión local; no publica en Cosmos. La corrección del error interno real requiere validación del backend.</div><div class="twocol"><section class="card"><h2>Configurar versión de propuesta</h2><div class="grid2"><label class="field">Nombre de plantilla<input id="tpl-name" value="${esc(pda.port)} · ${esc(pda.service)}" required></label><label class="field">Ámbito<select id="tpl-scope"><option>Callao · DP World · Liner</option><option>Paracas · Tramp</option></select></label></div><h3>Conceptos complementarios a revisar</h3><p class="muted">Añadir conceptos pendientes no reemplaza ni duplica los existentes. No se inventa su tarifa.</p><div class="checkboxes">${['Carga de contenedores llenos','Descarga de contenedores llenos','Carga de contenedores vacíos','Descarga de contenedores vacíos','Sanidad marítima','Derecho APN'].map((n,i)=>`<label><input type="checkbox" name="tpl-concept" value="${i}">${n}</label>`).join('')}</div><div class="divider"></div><div class="actions">${btn('Añadir seleccionados a esta PDA','apply-template')}${btn('Guardar versión local','save-template','primary')}</div><p class="help">La versión guarda los conceptos actuales con sus tarifas y fórmulas. No propaga cambios a otras PDA. Publicación y tarifas requieren aprobación del responsable.</p></section><aside class="card"><h2>Versiones locales</h2>${versions.map((v,i)=>`<p><span class="badge blue">v${i+1}</span> <b>${esc(v.name)}</b><br><small>${esc(v.at)} · ${v.rows.length} conceptos</small></p>`).join('')||'<p class="muted">No se han guardado versiones de propuesta.</p>'}<div class="divider"></div><h3>Control de calidad</h3><p class="muted">Nombre, ámbito y conceptos completos. Tarifas pendientes se conservan en borrador, pero impiden considerar la versión validada.</p></aside></div>`;}
function timeline(){return `<section class="card"><h2>Historial de esta simulación</h2><p class="muted">Cambios locales. No corresponde al historial de la PDA real en Cosmos.</p><div class="timeline">${history.map(e=>`<div class="event"><small>${esc(e.at)}</small><p>${esc(e.text)}</p></div>`).join('')}</div></section>`;}
function review(){return `${crumb('Cambios y validaciones')}<div class="heading"><div><div class="kicker">REUNIÓN DE CIERRE · COMERCIAL</div><h1>12 cambios. Una propuesta para revisar.</h1><span class="muted">Trazabilidad a los 9 tickets comerciales · sin modificar Monday</span></div><span class="spacer"></span>${btn('Volver al mockup','back-detail','primary')}</div><div class="notice warn">Las casillas solo registran que revisaste el punto en este navegador; no equivalen a aceptación formal. Validar con María, Pierre, Alonso, Jenny y César según corresponda.</div><div class="reviewgrid">${requirements.map(([id,title,ticket,current,proposed,validation,source,target])=>`<article class="req"><div class="bar" style="margin-bottom:12px"><span class="id">${id} /</span><h3>${title}</h3><span class="spacer"></span><a href="${board+ticket}" target="_blank" rel="noopener">#${ticket} ↗</a></div><p><b>Hallazgo:</b> ${current}</p><p><b>Propuesta:</b> ${proposed}</p><p class="reqnote"><b>Pendiente de validar:</b> ${validation}</p><small>Fuente: ${source}</small><div class="bar" style="margin:12px 0 0"><label class="check"><input type="checkbox" data-decision="${id}" ${decisions[id]?'checked':''}> Revisado en esta sesión</label><span class="spacer"></span>${btn('Ver en mockup →','jump','small',`data-target="${target}"`)}</div></article>`).join('')}</div><p class="help">Alcance: réplica parcial de pantallas observadas y prototipo funcional local. No implementa maestros, backend, provisiones, correo ni publicación de plantillas.</p>`;}
function modal(title,body,actions){$('#modal').innerHTML=`<h2>${title}</h2>${body}<div class="actions">${btn('Cancelar','close')}${actions}</div>`;$('#modal').showModal();}
function approvalIssues(){const issues=[];for(const [k,n] of [['vessel','Nave o referencia TBN'],['client','Cliente'],['billTo','Facturar por cuenta de'],['voyage','Viaje o referencia'],['service','Tipo de servicio'],['agency','Agenciamiento'],['operation','Operación'],['cargo','Tipo de carga'],['port','Puerto'],['terminal','Terminal'],['eta','ETA'],['etd','ETD'],['currency','Moneda']])if(!pda[k]||pda[k]==='Por definir')issues.push(n+' pendiente');if(pda.clientMode==='Provisional')issues.push('Cliente provisional debe confirmarse o derivarse a Datos Maestros antes de aprobar');if(pda.eta&&pda.etd&&pda.etd<pda.eta)issues.push('ETD no puede ser anterior a ETA');if(pda.port==='Callao'&&pda.terminal==='Terminal Portuario Paracas'||pda.port==='Paracas'&&pda.terminal==='DP World Callao S.R.L.')issues.push('Puerto y terminal no coinciden');if(!(Number(pda.exchange)>0))issues.push('Tipo de cambio debe ser positivo');if(!rows.some(r=>r.enabled))issues.push('Debe existir al menos un concepto');if(E.totals(rows,pda).pending)issues.push('Clasificar impuestos y completar las bases de cálculo de todos los conceptos incluidos');if(rows.some(r=>r.group==='surcharge'&&r.enabled))issues.push('Recargos manuales activos requieren revisión externa; no se simula su aprobación automática');return issues;}
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.field){pda[t.dataset.field]=t.value;changed('Dato actualizado: '+t.dataset.field);if(t.dataset.field==='vesselMode')render();}if(t.dataset.row){const r=rows.find(x=>x.id===Number(t.dataset.row));const k=t.dataset.key;r[k]=t.type==='checkbox'?t.checked:t.value;if(k==='provider')r.validated=false;changed(`${r.es}: ${k} actualizado`);render();}if(t.hasAttribute('data-language')){lang=t.value;render();}if(t.dataset.decision){decisions[t.dataset.decision]=t.checked;store();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='menu'){$('#navmenu').hidden=!$('#navmenu').hidden;return;}
 if(a==='close'){$('#modal').close();return;}
 if(a==='reference-duplicate'){toast('Referencia visual: botón Duplicar mostrado tal como existe hoy. No se creó una PDA real.');return;}
 if(a==='load-sample'){modal('Cargar escenario de referencia','<p>Se conservará una copia local del escenario actual y se restablecerá la propuesta PDA35 con todos sus impuestos pendientes de validar.</p>',btn('Cargar PDA35','confirm-sample','primary'));return;}
 if(a==='confirm-sample'){try{localStorage.setItem('cosmos-pda-mockup-backup',JSON.stringify({pda,rows,history,versions,decisions}));}catch{toast('No se pudo conservar la copia; se mantiene el escenario actual.');return;}pda=sample();rows=sampleRows();history=[{at:new Date().toLocaleString('es-PE'),text:'Escenario PDA35 cargado desde el PDF. Impuestos pendientes, sin aprobación.'}];store();$('#modal').close();page='detail';tab='general';render();return;}
 if(['actual','proposed'].includes(a)){mode=a==='actual'?'actual':'proposed';page='detail';tab='general';render();return;}
 if(['list','templates','review'].includes(a)){page=a;if(a==='templates')mode='proposed';render();return;}
 if(a==='back-detail'){page='detail';mode='proposed';tab='general';render();return;}
 if(a==='jump'){mode='proposed';if(['list','templates'].includes(b.dataset.target)){page=b.dataset.target;}else{page='detail';tab=b.dataset.target;}render();return;}
 if(a==='tab'){tab=b.dataset.tab;render();return;}
 if(['document','history'].includes(a)){page='detail';tab=a;render();return;}
 if(a==='save'){log('Borrador guardado localmente, sin exigir maestros completos.');if(store())toast('Borrador guardado en este navegador. Cosmos y Monday no se modificaron.');return;}
 if(a==='new'){modal('Nueva PDA · borrador flexible','<p>Se guardará la propuesta actual y se abrirá una nueva PDA Tramp con nave provisional. No se crea nada en Cosmos.</p>',btn('Crear borrador local','confirm-new','primary'));return;}
 if(a==='confirm-new'){if(!store())return;pda={...sample(),id:'BORRADOR-'+Date.now().toString().slice(-6),vessel:'TBN',vesselMode:'Provisional / TBN',voyage:'',grt:'',loa:'',client:'',billTo:'',clientMode:'Provisional',service:'Tramp',type:'Por definir',cargo:'Por definir',eta:'',etd:'',template:'',imo:'',flag:'',lastPort:''};rows=[];history=[{at:new Date().toLocaleString('es-PE'),text:'Borrador Tramp/TBN iniciado sin nave ni cliente en el maestro.'}];$('#modal').close();mode='proposed';page='detail';tab='general';render();toast('Nueva PDA local. Puedes guardar sin completar los particulares.');return;}
 if(a==='open-record'){if(b.dataset.origin==='Referencia observada')mode='actual';else mode='proposed';page='detail';tab='general';render();return;}
 if(a==='search'){document.querySelectorAll('[data-filter]').forEach(x=>filter[x.dataset.filter]=x.value);render();return;}
 if(a==='clear-search'){filter={};render();return;}
 if(a==='client'){modal('Buscar cliente / alta provisional',`<label class="field">Razón social<input id="c-name" list="clients" value="${esc(pda.client)}"><datalist id="clients"><option>ZIM INTEGRATED SHIPPING SERVICE LTD</option></datalist></label><div class="grid2"><label class="field">Dirección<input id="c-address" value="${esc(pda.address)}"></label><label class="field">Contacto<input id="c-contact" value="${esc(pda.contact)}"></label></div><label class="field">Correo<input id="c-email" type="email" value="${esc(pda.email)}"></label><p class="help">Solo ZIM está incluido como coincidencia de referencia. Cualquier otro nombre se conserva provisionalmente, sin alta en SAF. Datos opcionales para borrador.</p>`,btn('Usar cliente en borrador','save-client','primary'));return;}
 if(a==='save-client'){const name=$('#c-name').value.trim();if(!name){toast('Ingresa al menos una razón social para identificar al cliente.');return;}if(!$('#c-email').checkValidity()){toast('Revisa el formato del correo.');return;}pda.client=name;pda.clientMode=name==='ZIM INTEGRATED SHIPPING SERVICE LTD'?'Registrado':'Provisional';pda.address=$('#c-address').value;pda.contact=$('#c-contact').value;pda.email=$('#c-email').value;changed('Cliente seleccionado; facturar a se mantiene independiente.');$('#modal').close();render();return;}
 if(a==='add-service'){modal('Nuevo concepto',`<div class="grid2"><label class="field">Nombre en español<input id="r-es"></label><label class="field">Nombre en inglés<input id="r-en"></label></div><label class="field">Categoría<select id="r-group">${Object.entries(groups).filter(([k])=>k!=='surcharge').map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></label><p class="help">Se agregará con tarifa e IGV pendientes. Completa ambos antes de aprobar.</p>`,btn('Agregar','save-service','primary'));return;}
 if(a==='save-service'){const es=$('#r-es').value.trim(),en=$('#r-en').value.trim();if(!es||!en){toast('Completa los nombres ES y EN para evitar un PDF mezclado.');return;}if(rows.some(r=>r.es.toLowerCase()===es.toLowerCase())){toast('Este concepto ya existe. Ajusta el existente.');return;}rows.push({id:Date.now(),es,en,group:$('#r-group').value,rate:'',qty:1,unit:'Servicio',tax:'pending',enabled:true,source:'Concepto de propuesta',provider:'',validated:false,reason:''});changed('Concepto agregado: '+es);$('#modal').close();render();return;}
 if(a==='adjust'){const r=rows.find(r=>r.id===Number(b.dataset.id));modal('Ajuste documentado · '+esc(r.es),`<label class="field">Motivo / evidencia<textarea id="adjust-reason">${esc(r.reason)}</textarea></label><p class="help">Modifica tarifa o cantidad en la tabla. El motivo queda en el historial de la simulación.</p>`,btn('Guardar motivo','save-adjust','primary',`data-id="${r.id}"`));return;}
 if(a==='save-adjust'){const reason=$('#adjust-reason').value.trim();if(!reason){toast('Describe el motivo del ajuste.');return;}const r=rows.find(r=>r.id===Number(b.dataset.id));r.reason=reason;changed('Ajuste en '+r.es+': '+reason);$('#modal').close();render();return;}
 if(a==='add-surcharge'){const base=rows.find(r=>r.id===Number($('#s-base').value)),pct=$('#s-percent').value,reason=$('#s-reason').value.trim(),provider=$('#s-provider').value.trim();if(!base||pct===''||!(Number(pct)>0)||Number(pct)>1000||!reason||!provider){toast('Completa servicio base, porcentaje positivo (máximo 1000%), sustento y proveedor.');return;}const v=E.calc(base,pda);if(v.missing){toast('Completa primero la tarifa y base del servicio seleccionado.');return;}rows.push({id:Date.now(),group:'surcharge',es:'Recargo · '+base.es,en:'Surcharge · '+base.en,rate:E.round(v.net*Number(pct)/100),qty:1,unit:'Servicio',tax:'pending',enabled:true,provider,validated:false,source:'Registro manual',reason:`${pct}% de USD ${money(v.net)}; ${reason}; fuente: ${provider}; base congelada`});changed('Recargo manual incorporado a la base común de cálculo.');render();toast('Recargo agregado. Revisa su IGV en Servicios y cálculos.');return;}
 if(a==='validate-service'){const r=rows.find(r=>r.id===Number(b.dataset.id));if(!r.validated&&!r.provider.trim()){toast('Debes seleccionar un proveedor antes de validar este servicio.');return;}r.validated=!r.validated;log(`${r.es}: validación operativa ${r.validated?'simulada':'retirada'}.`);render();return;}
 if(a==='apply-template'){const names=[['Carga de contenedores llenos','Loaded container loading'],['Descarga de contenedores llenos','Loaded container unloading'],['Carga de contenedores vacíos','Empty container loading'],['Descarga de contenedores vacíos','Empty container unloading'],['Sanidad marítima','Maritime health clearance'],['Derecho APN','Port authority charge']];let count=0;document.querySelectorAll('[name="tpl-concept"]:checked').forEach(x=>{const [es,en]=names[Number(x.value)];if(!rows.some(r=>r.es===es)){rows.push({id:Date.now()+Number(x.value),es,en,group:Number(x.value)<4?'cargo':'authority',rate:'',qty:1,unit:Number(x.value)<4?'Contenedor':'Servicio',tax:'pending',enabled:true,source:'Plantilla · tarifa pendiente',reason:'',provider:'',validated:false});count++;}});changed(`${count} conceptos complementarios añadidos sin duplicar existentes.`);toast(`${count} conceptos añadidos. Tarifas y aplicación por validar.`);return;}
 if(a==='save-template'){const name=$('#tpl-name').value.trim();if(!name){toast('El nombre de la plantilla es obligatorio. Tu edición se conserva.');return;}if(!rows.length){toast('Añade al menos un concepto antes de guardar la plantilla.');return;}versions.push({name,scope:$('#tpl-scope').value,at:new Date().toLocaleString('es-PE'),rows:JSON.parse(JSON.stringify(rows))});pda.template=name+' · propuesta v'+versions.length;log('Versión local guardada: '+pda.template);if(store()){render();toast('Versión de propuesta guardada. No publicada; pendientes conservados.');}return;}
 if(a==='approve'){const issues=approvalIssues();modal('Revisión antes de aprobar',issues.length?`<div class="notice warn">Faltan ${issues.length} comprobaciones.</div><ul>${issues.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p class="help">Estos mandatorios son una recomendación pendiente de validar. El borrador puede guardarse de todas formas.</p>`:'<p>Los datos y cálculos del escenario están completos. Esta aprobación es solo una demostración local; no implica conformidad tributaria ni aprobación en Cosmos.</p>',issues.length?btn('Entendido','close','primary'):btn('Aprobar solo en mockup','confirm-approve','primary'));return;}
 if(a==='confirm-approve'){pda.status='Aprobada';log('Aprobación simulada. Sin efectos en el sistema real.');store();$('#modal').close();render();return;}
 if(a==='send'){const issues=approvalIssues();if(issues.length||pda.status!=='Aprobada'||lang==='en'&&pda.remarksEs&&!pda.remarksEn){toast('Para simular envío: completa la revisión, aprueba el escenario y traduce las observaciones. La vista previa sigue disponible.');return;}pda.sent=true;log('Envío simulado; ningún correo fue enviado.');store();render();toast('Envío simulado. No se envió ningún correo.');return;}
 if(a==='print'){if(lang==='en'&&pda.remarksEs&&!pda.remarksEn){toast('Falta traducir las observaciones a inglés. Completa ese campo antes de exportar.');return;}window.print();return;}
});
// La renderización inicial se ejecuta al final, después de cargar las reglas v2.
function services(){return servicesFixed();}

/* Iteración 2 · decisiones confirmadas por Comercial. Estas funciones sobrescriben
   la primera versión sin alterar la vista "Actual · referencia". */
const primaryStatesV2=['Creado','Aprobado','Anulado'];
const lifecycleV2=['Creado','Enviado','Validado','Aprobado','Completado'];
const rejectionFlowV2=['Rechazado','Ajuste','Enviado','Validado','Aprobado','Completado'];
const containerLabelsV2={full20Load:'20′ llenos · carga',full20Unload:'20′ llenos · descarga',empty20Load:'20′ vacíos · carga',empty20Unload:'20′ vacíos · descarga',full40Load:'40′ llenos · carga',full40Unload:'40′ llenos · descarga',empty40Load:'40′ vacíos · carga',empty40Unload:'40′ vacíos · descarga'};
const serviceCodesV2={
 'Comisión de agencia':'AGENCY-COMMISSION',
 'Uso de amarradero':'PORT-BERTH',
 'Practicaje · exportación':'PORT-PILOTAGE-EXPORT',
 'Lancha · servicio continuado':'PORT-LAUNCH-CONT',
 'Remolcaje':'PORT-TOWAGE',
 'Despacho':'PORT-CLEARANCE',
 'Recepción':'AUTH-RECEPTION',
 'Ayudas a la navegación':'AUTH-NAV-AIDS'
};
function ensurePdaV2(){
 if(pda.status==='Creada')pda.status='Creado';
 if(pda.status==='Aprobada')pda.status='Aprobado';
 if(pda.status==='Anulada')pda.status='Anulado';
 if(!pda.status||!primaryStatesV2.includes(pda.status))pda.status='Creado';
 if(!pda.stage)pda.stage=pda.sent?'Enviado':'Creado';
 if(pda.status==='Aprobado')pda.stage='Aprobado';
 if(pda.status==='Anulado')pda.stage='Anulado';
 if(!pda.containers)pda.containers={};
 Object.keys(containerLabelsV2).forEach(k=>{if(!Number.isFinite(Number(pda.containers[k])))pda.containers[k]=0;});
 pda.containers.total=Object.keys(containerLabelsV2).reduce((s,k)=>s+Number(pda.containers[k]||0),0);
 if(!pda.surchargeConfig)pda.surchargeConfig={holidayPct:50,extensionPct:30,normalStart:'08:00',normalEnd:'18:00'};
 if(!pda.surchargesRecalculated)pda.surchargesRecalculated=false;
 if(!pda.associated)pda.associated=false;
 groups.authority[0]='Gastos por autoridades marítimas';
}
function currentStageV2(){ensurePdaV2();return pda.stage||'Creado';}
function primaryStatusV2(){ensurePdaV2();return pda.status;}
function workflowV2(){const stage=currentStageV2();return `<section class="workflow card"><div class="kicker">FLUJO DE ESTADOS</div><div class="flowline">${lifecycleV2.map(s=>`<span class="flowstep ${s===stage?'current':''} ${['Aprobado','Completado'].includes(s)&&stage===s?'green':''}">${s}</span>`).join('<span class="flowarrow">→</span>')}</div><div class="help">Rechazo: ${rejectionFlowV2.join(' → ')}. "Ajuste" permite editar y reenviar.</div></section>`;}
function associationV2(){const enabled=primaryStatusV2()==='Aprobado';return `<button data-action="associate" ${enabled?'':'disabled'} title="${enabled?'Asociar la PDA aprobada al servicio y viaje':'La asociación se habilita únicamente después de aprobar la PDA'}">Asociar PDA a nave/viaje</button>`;}
function detail(){
 const actual=mode==='actual';
 const actualStates=['Anulada','Aprobada','Borrador','Completada','Creada','En Ajuste','En Viaje','Rechazada','Validada'];
 ensurePdaV2();
 const proposalHead=`<span class="tagline">${esc(pda.vessel||'Nave por definir')} · ${esc(pda.service)} · ${esc(pda.port||'Puerto por definir')}</span> <span class="badge blue">${esc(primaryStatusV2())}</span> <span class="badge">${esc(currentStageV2())}</span>`;
 return `${crumb(actual?'Ver PDA':'Editar propuesta')}<div class="heading"><div><div class="kicker">${actual?'REFERENCIA OBSERVADA · SOLO LECTURA':'COMERCIAL / PDA · PROPUESTA DE DEFINICIÓN'}</div><h1>${actual?'PDA2026000035PECLL':esc(pda.id)}</h1>${actual?`<div class="statusflow" aria-label="Estados de la PDA">${actualStates.map(s=>`<span class="badge ${s==='En Viaje'?'green':''}">${s}</span>`).join('')}</div>`:proposalHead}</div><span class="spacer"></span><div class="actions">${btn('Historial','history')}${actual?btn('Duplicar','reference-duplicate'):''}${!actual?btn('Vista previa','document'):''}${!actual?btn('Guardar borrador','save','primary'):''}</div></div>${actual?`<div class="notice actualnote">Esta réplica cubre las pantallas observadas de la PDA35, no todo el portal. Pantalla: USD 4,811.89; PDF recibido: USD 6,726.61. Son dos evidencias distintas; no se ha verificado que correspondan a la misma versión.</div>`:`<div class="notice"><span>ⓘ</span><div><b>Propuesta para validar con Comercial, Agenciamiento y Facturación.</b> Puedes guardar datos incompletos. Las tarifas vienen del PDF; fórmulas, impuestos y mandatorios deben confirmarse antes de aprobación. Todo se guarda solo en este navegador.<br><span class="help"><b>(*)</b> obligatorio al aprobar; sin (*) es opcional o referencial en el borrador.</span></div></div>${workflowV2()}`}<div class="tabs">${(actual?[['general','Información General'],['services','Detalle'],['document','PDF recibido']]:[['general','Información general'],['services','Servicios y cálculos'],['surcharges','Recargos'],['document','Documento'],['providers','Validación operativa'],['history','Historial']]).map(([id,t])=>btn(t,'tab',tab===id?'active':'',`data-tab="${id}"`)).join('')}</div>${actual?actualContentFixed():({general:general,services:servicesFixed,surcharges:surcharges,document:documentView,providers:providers,history:timeline}[tab]||general)()}${!actual&&tab!=='document'?`<div class="footerbar"><span class="muted">${pda.template?esc(pda.template):'Sin plantilla aplicada'}<br><small>Una edición posterior invalida la aprobación simulada.</small></span><span class="spacer"></span>${associationV2()}${btn('Nueva PDA / TBN','new')}${btn('Revisar para aprobar','approve','primary')}</div>`:''}`;
}
function general(){return `<div class="grid3"><section class="card"><div class="cardhead"><span class="ico">♧</span><h2>Datos del buque</h2></div>${field('Origen de la nave','vesselMode','text',['Registrada','Provisional / TBN'])}${field('Nave o referencia provisional (*)','vessel','text',null,'(*) obligatorio al aprobar; puedes escribir TBN o una nave nueva. No se da de alta en el maestro.')}${field('Tipo de nave','type','text',['Portacontenedores','Granelero','Tanque','Por definir'])}<div class="grid2">${field('Viaje / referencia (*)','voyage')}${field('TRG / GRT (si aplica)','grt','number',null,'Obligatorio solo si la plantilla o tarifa lo utiliza.')}</div><div class="grid2">${field('Eslora / LOA (si aplica)','loa','number',null,'Obligatoria solo si la plantilla o tarifa lo utiliza.')}</div><p class="formbottom">Los datos personales y de identificación de la nave se administran fuera del flujo comercial de la PDA.</p></section><section class="card"><div class="cardhead"><span class="ico">♙</span><h2>Cliente / Facturación</h2></div>${field('Cliente solicitante (*)','client','text',null,'(*) debe existir un cliente facturable confirmado al aprobar.')}<div class="actions" style="margin:-7px 0 19px">${btn('Buscar / alta provisional','client','small')}<span class="badge ${pda.clientMode==='Provisional'?'amber':''}">${esc(pda.clientMode)}</span></div>${field('Cliente facturador (opcional en borrador) (*)','billTo','text',null,'Opcional mientras está en Creado; obligatorio al aprobar.') }<div class="grid2">${field('Head owner (opcional)','owner')}${field('Charterer / disponent (opcional)','charterer')}</div>${field('Broker (opcional)','broker')}${field('Technical manager (opcional)','manager')}${field('Enviar liquidación a (opcional)','settlementTo')}<div class="grid2">${field('Moneda (*)','currency','text',['USD'])}${field('Tipo de cambio referencial (*)','exchange','number',null,'(*) positivo al aprobar; tarifas de ejemplo expresadas en USD.')}</div>${field('Condición de pago','payment','text',['Por definir','Contado','Crédito 30 días'])}<p class="formbottom">Validar roles, pagador y eventual facturación por servicio. No se genera un registro en SAF ni un comprobante.</p></section><section class="card"><div class="cardhead"><span class="ico">⚙</span><h2>Configuración operativa</h2></div><div class="grid2">${field('Tipo de servicio (*)','service','text',['Liner','Tramp'])}${field('Agenciamiento (*)','agency','text',['Agente Marítimo','Agente Protector'])}</div>${field('Operación (*)','operation','text',['Importación / Exportación','Importación','Exportación','Otros'])}${field('Tipo de carga (*)','cargo','text',['Contenerizada','Granel sólido','Granel líquido','Carga general','Por definir'])}<div class="grid2">${field('Puerto (*)','port','text',['Callao','Paracas','Por definir'])}${field('Terminal (*)','terminal','text',['DP World Callao S.R.L.','Terminal Portuario Paracas','Por definir'])}</div><span class="help">Catálogo de demostración. Faltantes: dependencia de Datos Maestros.</span><div class="grid2">${field('ETA (*) · fecha y hora local','eta','datetime-local')}${field('ETD (*) · fecha y hora local','etd','datetime-local')}</div>${field('Último puerto (opcional)','lastPort')}<label class="field">Observaciones para documento (inglés)<textarea data-field="remarksEn" placeholder="Ingresar observaciones que se imprimirán en inglés">${esc(pda.remarksEn)}</textarea></label></section></div>`;}
function containerTotalV2(){ensurePdaV2();return pda.containers.total;}
function syncContainerRowsV2(){const total=containerTotalV2();rows.filter(r=>r.unit==='Contenedor').forEach(r=>{r.qty=total;});}
function containerPanelV2(){return `<section class="card container-panel"><div class="bar"><div><div class="kicker">AGenciamiento · CARGA</div><h2 style="margin:0">Cantidad de contenedores</h2></div><span class="badge blue">Fuente: Agenciamiento</span></div><p class="muted">La cantidad se sincroniza con la PDA y actualiza las tarifas de servicios configurados por contenedor.</p><div class="container-grid">${Object.entries(containerLabelsV2).map(([k,label])=>`<label class="field">${label}<input type="number" min="0" step="1" data-container="${k}" value="${Number(pda.containers[k]||0)}"></label>`).join('')}</div><div class="notice">Total configurado: <b>${containerTotalV2()}</b> contenedores. Las diferencias con Agenciamiento deben corregirse antes de aprobar.</div><p class="help">El mantenimiento del servicio define si aplica por tipo de contenedor, carga/descarga y lleno/vacío.</p></section>`;}
function homologatedCodeV2(r){return serviceCodesV2[r.es]||r.code||'PENDIENTE-HOMOLOGAR';}
function servicesFixed(){ensurePdaV2();syncContainerRowsV2();const t=E.totals(rows,pda);const body=Object.entries(groups).map(([g,names])=>{const rr=rows.filter(r=>r.group===g);if(!rr.length)return '';const sub=E.totals(rr,pda);return `<tr class="group"><td colspan="14">${names[0]} <span class="badge">${rr.length}</span></td></tr>${rr.map(r=>{const qty=r.unit==='Contenedor'?containerTotalV2():r.qty;const v=E.calc({...r,qty},pda);return `<tr><td><input aria-label="Incluir ${esc(r.es)}" type="checkbox" data-row="${r.id}" data-key="enabled" ${r.enabled?'checked':''}></td><td><div class="service">${esc(r.es)}</div><small>${esc(r.source)} · ${homologatedCodeV2(r)}</small>${v.missing?'<span class="help" style="color:#ae6500">Completar tarifa o base</span>':''}</td><td><select aria-label="Tarifa unitaria ${esc(r.es)}" data-row="${r.id}" data-key="unit">${['Servicio','Hora','Contenedor','LOA × horas','TRG × cantidad'].map(x=>option(x,r.unit)).join('')}</select><span class="help">${r.unit==='LOA × horas'?`× ${esc(pda.loa||'?')} m`:r.unit==='TRG × cantidad'?`× ${esc(pda.grt||'?')} TRG`:'Tarifa × cantidad'}</span></td><td><input aria-label="Tarifa ${esc(r.es)}" type="number" min="0" step="any" data-row="${r.id}" data-key="rate" value="${r.rate}"></td><td>USD</td><td><input aria-label="Cantidad ${esc(r.es)}" type="number" min="0" step="any" data-row="${r.id}" data-key="qty" value="${qty}"></td><td>—</td><td><select aria-label="IGV ${esc(r.es)}" data-row="${r.id}" data-key="tax">${Object.entries(taxNames).map(([k,vv])=>option(k,r.tax,vv)).join('')}</select></td><td class="num">${money(v.net)}</td><td class="num">${r.tax==='pending'&&r.enabled?'—':money(v.tax)}</td><td class="num"><b>${money(v.total)}</b></td><td>${r.reason?esc(r.reason):'—'}</td><td>${r.provider?(r.validated?'Validado':'Pendiente'):'—'}</td><td>${btn('Ajuste','adjust','small',`data-id="${r.id}"`)}</td></tr>`;}).join('')}<tr class="actual-subtotal"><td colspan="10" class="num"><b>Subtotal ${esc(names[0])}</b></td><td class="num"><b>${money(sub.total)}</b></td><td colspan="3"></td></tr>`;}).join('');return `<div class="bar"><div><h2>Conceptos y base de cálculo</h2><span class="muted">Tarifas homologadas · cambia valores para comparar escenarios</span></div><span class="spacer"></span>${btn('PDA Plantilla','templates')}${btn('+ Agregar concepto','add-service','primary')}</div>${containerPanelV2()}<div class="notice warn">${t.pending} concepto(s) pendiente(s) de tarifa, base o impuesto. La aprobación permanece bloqueada hasta completar los pendientes.</div><div class="tablewrap"><table><thead><tr><th>Usar</th><th>Concepto / origen</th><th>Tarifa Unitaria</th><th>Tarifa</th><th>Moneda</th><th>Cantidad</th><th>A/E</th><th>Tratamiento IGV</th><th class="num">Base neta</th><th class="num">IGV</th><th class="num">Total</th><th>Comentarios</th><th>Val. Ope.</th><th></th></tr></thead><tbody>${body}</tbody></table></div>${metrics(t)}<div class="notice" style="margin-top:20px">Ayudas a la navegación: 0.03 × 21,667 × 1 = <b>650.01</b>. Amarradero: 1.50 × 171.98 × 10 = <b>2,579.70</b>. El motor compartido alimenta la PDA y el documento.</div>`;}
function autoSurchargesV2(){ensurePdaV2();const base=rows.find(r=>r.enabled&&r.group!=='surcharge');if(!base)return [];const baseValue=E.calc(base,pda);if(baseValue.missing)return [];const cfg=pda.surchargeConfig,holidayDates={'2026-07-28':'Fiestas Patrias','2026-07-29':'Fiestas Patrias','2026-08-30':'Santa Rosa de Lima','2026-10-08':'Combate de Angamos','2026-11-01':'Día de Todos los Santos','2026-12-08':'Inmaculada Concepción','2026-12-25':'Navidad'},seen=new Set(),out=[];[pda.eta,pda.etd].filter(Boolean).forEach(value=>{const day=String(value).slice(0,10),date=new Date(value),holiday=holidayDates[day];if(holiday&&!seen.has('holiday:'+day)){out.push({kind:'holiday',label:'Recargo por feriado · '+holiday,pct:Number(cfg.holidayPct),amount:E.round(baseValue.net*Number(cfg.holidayPct)/100),source:'Maestro de recargos'});seen.add('holiday:'+day);}const raw=String(value).slice(11,16);if(raw&&raw!=='00:00'&&date.toString()!=='Invalid Date'){const hh=Number(raw.slice(0,2))+Number(raw.slice(3,5))/60,start=Number(String(cfg.normalStart).slice(0,2)),end=Number(String(cfg.normalEnd).slice(0,2));if(hh<start||hh>end){const key='extension:'+day+':'+raw;if(!seen.has(key)){out.push({kind:'extension',label:'Recargo por extensión horaria · '+day+' '+raw,pct:Number(cfg.extensionPct),amount:E.round(baseValue.net*Number(cfg.extensionPct)/100),source:'Maestro de recargos'});seen.add(key);}}}});return out;}
function surcharges(){ensurePdaV2();const auto=autoSurchargesV2(),autoTotal=auto.reduce((s,x)=>s+x.amount,0);return `<div class="twocol"><section class="card"><div class="kicker">FASE 1 · CÁLCULO AUTOMÁTICO</div><h2>Recargos por reglas operativas</h2><p class="muted">El sistema revisa feriados y extensión horaria a partir de ETA/ETD y recalcula cuando cambian los datos de la PDA.</p><div class="grid2"><label class="field">Recargo feriado (%)<input type="number" min="0" data-config="holidayPct" value="${pda.surchargeConfig.holidayPct}"></label><label class="field">Extensión horaria (%)<input type="number" min="0" data-config="extensionPct" value="${pda.surchargeConfig.extensionPct}"></label><label class="field">Inicio horario normal<input type="time" data-config="normalStart" value="${pda.surchargeConfig.normalStart}"></label><label class="field">Fin horario normal<input type="time" data-config="normalEnd" value="${pda.surchargeConfig.normalEnd}"></label></div>${btn('Recalcular recargos','recalc-surcharges','primary')}<p class="help">Configuración demostrativa del Maestro de recargos; porcentajes y calendario deben ser confirmados por Facturación.</p></section><aside class="card"><span class="badge amber">Por validar con el usuario</span><h2 style="margin-top:17px">Mantenimiento del servicio</h2><p>La regla puede asociarse al servicio y terminal desde el catálogo homologado. Un ajuste manual excepcional exige sustento y autorización.</p>${btn('Ver ticket y decisiones','review')}</aside></div><section class="card" style="margin-top:20px"><div class="bar"><h2 style="margin:0">Resultado del recálculo</h2><span class="badge ${pda.surchargesRecalculated?'green':'amber'}">${pda.surchargesRecalculated?'Recalculado':'Pendiente de recalcular'}</span></div>${auto.map(x=>`<div class="summary-line"><span>${x.label} · ${x.pct}%</span><b>USD ${money(x.amount)}</b></div>`).join('')||'<p class="muted">No se detectan feriados ni extensiones con las fechas y horas actuales.</p>'}<div class="actual-total"><div class="grand"><span>RECARGOS AUTOMÁTICOS</span><span>USD ${money(autoTotal)}</span></div></div></section><section class="card" style="margin-top:20px"><h2>Ajustes manuales excepcionales</h2><p class="muted">Solo para casos no cubiertos por el maestro; requieren causa, proveedor/fuente y revisión antes de aprobar.</p>${rows.filter(r=>r.group==='surcharge').map(r=>`<p><b>${esc(r.es)}</b> · USD ${money(r.rate)}<br><small>${esc(r.reason)}</small></p>`).join('')||'<p class="muted">No hay ajustes manuales registrados.</p>'}</section>`;}
function documentView(){const en=lang==='en',t=E.totals(rows,pda),tr=(a,b)=>en?b:a,tx={pending:['Pendiente','Pending'],excluded:['Gravado 18%','Taxable 18%'],included:['Incluido 18%','Included 18%'],exempt:['Exonerado','Exempt'],unaffected:['Inafecto','Not subject']},unitName=u=>en?({'Servicio':'Service','Hora':'Hour','Contenedor':'Container','LOA × horas':'LOA × hours','TRG × cantidad':'GRT × quantity'}[u]||'Service'):u,val=k=>esc(pda[k]||tr('Por definir','To be defined')),displayDate=v=>v?new Date(v).toLocaleString(en?'en-GB':'es-PE',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):tr('Por definir','To be defined'),translateValue=v=>en?({'Portacontenedores':'Container ship','Granelero':'Bulk carrier','Tanque':'Tanker','Por definir':'To be defined','Contenerizada':'Containerized','Granel sólido':'Dry bulk','Granel líquido':'Liquid bulk','Carga general':'General cargo','Contado':'Cash','Crédito 30 días':'30-day credit','Servicio':'Service'}[v]||v):v;return `<div class="doccontrols"><label for="doclang">Idioma del documento</label><select id="doclang" data-language>${option('es',lang,'Español')}${option('en',lang,'English')}</select><span class="spacer"></span>${btn('Vista previa para cliente','client-preview')}${btn('Descargar PDF para cliente','print-client','primary')}</div><div class="docscroll"><article class="paper" lang="${lang}"><div class="paperhead">${logo()}<div class="num"><b>${esc(pda.id)}</b><div class="help">${tr('SIMULACIÓN · NO VÁLIDA PARA COBRO','SIMULATION · NOT VALID FOR PAYMENT')}</div></div></div><h1>${tr('CUENTA PROFORMA DE DESEMBOLSOS (PDA)','PROFORMA DISBURSEMENT ACCOUNT (PDA)')}</h1><div class="notice warn" style="font-size:10px">${tr('Documento preliminar. Tratamiento tributario, tarifas y fórmulas sujetos a validación.','Preliminary document. Tax treatment, rates and formulas are subject to validation.')} ${t.pending?tr(`${t.pending} conceptos pendientes.`,`${t.pending} pending items.`):''}</div><div class="docmeta"><div><span>${tr('Cliente','Client')}</span><b>${val('client')}</b></div><div><span>${tr('Fecha de emisión','Issue date')}</span><b>${tr('17 sep 2026','17 Sep 2026')}</b></div><div><span>${tr('Facturar a','Bill to')}</span><b>${val('billTo')}</b></div><div><span>${tr('Moneda','Currency')}</span><b>${esc(pda.currency||'USD')}</b></div><div><span>${tr('Nave / viaje','Vessel / voyage')}</span><b>${val('vessel')} / ${val('voyage')}</b></div><div><span>${tr('Tipo de nave','Vessel type')}</span><b>${esc(translateValue(pda.type))}</b></div><div><span>${tr('Puerto / terminal','Port / terminal')}</span><b>${val('port')} / ${val('terminal')}</b></div><div><span>GRT / LOA</span><b>${Number(pda.grt).toLocaleString('en-US')} / ${money(pda.loa)} m</b></div><div><span>ETA / ETD</span><b>${displayDate(pda.eta)} / ${displayDate(pda.etd)}</b></div><div><span>${tr('Carga','Cargo')}</span><b>${esc(translateValue(pda.cargo))}</b></div><div><span>${tr('Tipo de cambio','Exchange rate')}</span><b>${money(pda.exchange)}</b></div><div><span>${tr('Condición de pago','Payment terms')}</span><b>${esc(translateValue(pda.payment))}</b></div></div><table><thead><tr><th>${tr('Concepto','Service')}</th><th>${tr('Unidad / base','Unit / basis')}</th><th class="num">${tr('Tarifa','Rate')}</th><th class="num">${tr('Cant.','Qty.')}</th><th>${tr('Impuesto','Tax')}</th><th class="num">${tr('Neto','Net')}</th><th class="num">${tr('IGV','VAT')}</th><th class="num">${tr('Total','Total')} USD</th></tr></thead><tbody>${Object.entries(groups).map(([g,n])=>{const list=rows.filter(r=>r.enabled&&r.group===g);if(!list.length)return '';return `<tr class="group"><td colspan="8">${n[en?1:0]}</td></tr>`+list.map(r=>{const v=E.calc(r,pda);return `<tr><td>${esc(en?r.en:r.es)}</td><td>${unitName(r.unit)}${r.unit==='LOA × horas'?` · ${money(pda.loa)}`:r.unit==='TRG × cantidad'?` · ${Number(pda.grt).toLocaleString('en-US')}`:''}</td><td class="num">${r.rate===''?'—':money(r.rate)}</td><td class="num">${r.qty}</td><td>${tx[r.tax][en?1:0]}</td><td class="num">${v.missing?'—':money(v.net)}</td><td class="num">${r.tax==='pending'?'—':money(v.tax)}</td><td class="num">${v.missing?'—':money(v.total)}</td></tr>`;}).join('')+`<tr><td colspan="5" class="num"><b>${tr('Subtotal','Subtotal')}</b></td><td class="num">${money(E.totals(list,pda).net)}</td><td class="num">${money(E.totals(list,pda).tax)}</td><td class="num"><b>${money(E.totals(list,pda).total)}</b></td></tr>`;}).join('')}</tbody></table><div class="docbottom"><div style="font-size:11px;line-height:1.8"><b>Cosmos Global Logistics S.A.C.</b><br>${tr('Datos bancarios omitidos en esta simulación.','Bank details omitted in this simulation.')}<br>${tr('No realizar transferencias con este documento.','Do not make transfers using this document.')}</div><div class="docsum"><div><span>${tr('Base gravada','Taxable net')}</span><b>${money(E.totals(rows.filter(r=>['included','excluded'].includes(r.tax)),pda).net)}</b></div><div><span>${tr('Exonerado / inafecto','Exempt / not subject')}</span><b>${money(E.totals(rows.filter(r=>['exempt','unaffected'].includes(r.tax)),pda).net)}</b></div><div><span>${tr('Base pendiente de clasificación','Net pending classification')}</span><b>${money(E.totals(rows.filter(r=>r.tax==='pending'),pda).net)}</b></div><div><span>${tr('Total neto','Net total')}</span><b>${money(t.net)}</b></div><div><span>${tr('IGV calculado (18%)','Calculated VAT (18%)')}</span><b>${money(t.tax)}</b></div><div class="grand"><span>${tr('Total provisional','Provisional total')}</span><span>USD ${money(t.total)}</span></div></div></div>${pda.remarksEn?`<div class="footnote"><b>${tr('OBSERVACIONES (EN)','REMARKS')}</b><p>${esc(pda.remarksEn).replace(/\n/g,'<br>')}</p></div>`:''}<div class="footnote">${tr('Documento generado con la misma base de cálculo de la pantalla. Valores de ejemplo para validación funcional, no tarifas ni impuestos aprobados.','Document generated from the same calculation model as the screen. Sample values for functional validation, not approved rates or tax treatment.')}</div></article></div>`;}
function listing(){ensurePdaV2();const data=[{...sample(),status:'Creado',stage:'Enviado',source:'Referencia observada'},{...pda,source:'Propuesta local'}];return `${crumb('Buscar PDA')}<div class="heading"><div><div class="kicker">COMERCIAL</div><h1>Buscar PDA</h1><span class="muted">Estados principales: ${primaryStatesV2.join(' · ')}. Enviado, Validado y otros son etapas del flujo.</span></div><span class="spacer"></span>${btn('+ Nueva PDA','new','primary')}</div><section class="card"><div class="filters"><label class="field">Código, nave, viaje o cliente<input data-filter="q" value="${esc(filter.q||'')}" placeholder="Ej. BOX ENDURANCE"></label><label class="field">Estado principal<select data-filter="state">${option('',filter.state||'','Todos')}${primaryStatesV2.map(x=>option(x,filter.state||'',x)).join('')}</select></label><label class="field">Tipo de servicio<select data-filter="service">${['','Liner','Tramp'].map(x=>option(x,filter.service||'',x||'Todos')).join('')}</select></label><label class="field">Puerto<select data-filter="port">${['','Callao','Paracas'].map(x=>option(x,filter.port||'',x||'Todos')).join('')}</select></label></div><div class="actions">${btn('Buscar','search','primary')}${btn('Limpiar','clear-search')}</div></section><div class="bar" style="margin-top:25px"><h2 style="margin:0">Resultados <span class="badge">2</span></h2><span class="spacer"></span><small>Escenarios locales · no es el listado completo de Monday/Cosmos</small></div><div class="tablewrap"><table><thead><tr><th>Código PDA / origen</th><th>Nave</th><th>Viaje</th><th>Puerto</th><th>Cliente</th><th>Estado</th><th>Etapa</th></tr></thead><tbody>${data.map(d=>`<tr><td>${btn(esc(d.id),'open-record','linkbtn',`data-origin="${d.source}"`)}<span class="help">${d.source}</span></td><td>${esc(d.vessel||'TBN')}</td><td>${esc(d.voyage||'—')}</td><td>${esc(d.port)}</td><td class="longname">${esc(d.client||'Por definir')}</td><td><span class="badge blue">${esc(d.status)}</span></td><td>${esc(d.stage||'Creado')}</td></tr>`).join('')}</tbody></table></div>`;}
function approvalIssues(){ensurePdaV2();const issues=[];for(const [k,n] of [['vessel','Nave o referencia TBN'],['client','Cliente'],['billTo','Cliente facturador'],['voyage','Viaje o referencia'],['service','Tipo de servicio'],['agency','Agenciamiento'],['operation','Operación'],['cargo','Tipo de carga'],['port','Puerto'],['terminal','Terminal'],['eta','ETA'],['etd','ETD'],['currency','Moneda']])if(!pda[k]||pda[k]==='Por definir')issues.push(n+' pendiente');if(pda.clientMode==='Provisional')issues.push('Cliente provisional debe confirmarse o derivarse a Datos Maestros antes de aprobar');if(pda.eta&&pda.etd&&pda.etd<pda.eta)issues.push('ETD no puede ser anterior a ETA');if((pda.port==='Callao'&&pda.terminal==='Terminal Portuario Paracas')||(pda.port==='Paracas'&&pda.terminal==='DP World Callao S.R.L.'))issues.push('Puerto y terminal no coinciden');if(!(Number(pda.exchange)>0))issues.push('Tipo de cambio debe ser positivo');if(!rows.some(r=>r.enabled))issues.push('Debe existir al menos un concepto');if(E.totals(rows,pda).pending)issues.push('Clasificar impuestos y completar las bases de cálculo de todos los conceptos incluidos');if(autoSurchargesV2().length&&!pda.surchargesRecalculated)issues.push('Recalcular recargos automáticos antes de aprobar');if(rows.some(r=>r.group==='surcharge'&&r.enabled))issues.push('Los ajustes manuales activos requieren revisión externa');return issues;}
function render(){ensurePdaV2();document.documentElement.lang='es';$('#app').innerHTML=shell();if(page==='detail'&&mode==='proposed'&&tab!=='document'){const f=$('.footerbar');f?.insertAdjacentHTML('beforeend',btn('Cargar ejemplo PDA35','load-sample'));}}

document.addEventListener('change',e=>{const t=e.target;if(t.dataset.container){ensurePdaV2();pda.containers[t.dataset.container]=Math.max(0,Number(t.value)||0);syncContainerRowsV2();pda.surchargesRecalculated=false;changed('Cantidad de contenedores actualizada desde Agenciamiento.');store();render();e.stopImmediatePropagation();return;}if(t.dataset.config){ensurePdaV2();pda.surchargeConfig[t.dataset.config]=t.value;changed('Regla de recargo actualizada.');pda.surchargesRecalculated=false;store();render();e.stopImmediatePropagation();}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='approve'){const issues=approvalIssues();modal('Revisión antes de aprobar',issues.length?`<div class="notice warn">Faltan ${issues.length} comprobaciones.</div><ul>${issues.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p class="help">El borrador puede guardarse, pero no asociarse a una nave de viaje hasta aprobarse.</p>`:'<p>Los datos y cálculos están completos. Esta aprobación es solo una demostración local; no implica aprobación en Cosmos.</p>',issues.length?btn('Entendido','close','primary'):btn('Aprobar solo en mockup','confirm-approve','primary'));e.stopImmediatePropagation();return;}if(a==='confirm-approve'){pda.status='Aprobado';pda.stage='Aprobado';pda.confirmed=true;log('Aprobación simulada. Sin efectos en el sistema real.');store();$('#modal').close();render();e.stopImmediatePropagation();return;}if(a==='send'){pda.sent=true;pda.stage='Enviado';log('Envío simulado; ningún correo fue enviado.');store();render();toast('Etapa Enviado simulada. No se envió ningún correo.');e.stopImmediatePropagation();return;}if(a==='print'||a==='print-client'){window.print();e.stopImmediatePropagation();return;}if(a==='client-preview'){modal('Vista previa para cliente','<p>Esta vista permite revisar la información y descargar el PDF. Antes de aprobar se mostrará como documento preliminar.</p>',btn('Descargar PDF para cliente','print-client','primary'));e.stopImmediatePropagation();return;}if(a==='recalc-surcharges'){pda.surchargesRecalculated=true;log('Recargos automáticos recalculados con las reglas vigentes.');store();render();toast('Recargos recalculados.');e.stopImmediatePropagation();return;}if(a==='associate'){if(primaryStatusV2()!=='Aprobado'){toast('La PDA debe estar Aprobada antes de asociarla a una nave de viaje.');}else{pda.associated=true;log('PDA asociada a nave/viaje. Simulación local.');store();render();toast('Asociación simulada.');}e.stopImmediatePropagation();return;}if(a==='validate-service'){const r=rows.find(x=>x.id===Number(b.dataset.id));if(!r)return;if(!r.validated&&!r.provider.trim()){toast('Debes seleccionar un proveedor antes de validar este servicio.');e.stopImmediatePropagation();return;}r.validated=!r.validated;if(rows.filter(x=>x.enabled).every(x=>x.validated)){pda.stage='Validado';}else if(pda.stage==='Validado'){pda.stage='Enviado';}log(`${r.es}: validación operativa ${r.validated?'simulada':'retirada'}.`);store();render();e.stopImmediatePropagation();return;}},true);
render();

// Vista pública del prototipo: únicamente propuesta, sin la réplica de referencia.
function shell(){mode='proposed';return `<header><div class="top">${logo()}<span class="branch muted">⌖ &nbsp; Callao⌄</span><span class="spacer"></span><span class="date muted">Lunes 14 de septiembre de 2026</span><span>🇵🇪</span><div class="avatar">AP</div></div><nav><span>◉ Dashboard</span><div class="navdrop">${btn('▱ &nbsp; PDA ⌄','menu','navactive')}<div id="navmenu" class="navmenu" hidden>${btn('PDA','list')}${btn('PDA Plantilla','templates')}</div></div><span>◇ Agenciamiento ⌄</span><span>◈ Tarifa</span><span>▤ Documentación ⌄</span><span>Atención al cliente</span><span>Liquidación</span><span>Tesorería</span><span>Data Maestra</span></nav></header><div class="studio"><b>LABORATORIO COMERCIAL</b><span class="badge blue">PROPUESTA</span><span>Mockup local · flujo de propuesta</span><span class="spacer"></span>${btn('12 cambios y validaciones ↗','review','review')}</div><main class="workspace">${content()}</main>`;}
function detail(){ensurePdaV2();const proposalHead=`<span class="tagline">${esc(pda.vessel||'Nave por definir')} · ${esc(pda.service)} · ${esc(pda.port||'Puerto por definir')}</span> <span class="badge blue">${esc(primaryStatusV2())}</span> <span class="badge">${esc(currentStageV2())}</span>`;return `${crumb('Editar propuesta')}<div class="heading"><div><div class="kicker">COMERCIAL / PDA · PROPUESTA DE DEFINICIÓN</div><h1>${esc(pda.id)}</h1>${proposalHead}</div><span class="spacer"></span><div class="actions">${btn('Historial','history')}${btn('Vista previa','document')}${btn('Guardar borrador','save','primary')}</div></div><div class="notice"><span>ⓘ</span><div><b>Propuesta para validar con Comercial, Agenciamiento y Facturación.</b> Puedes guardar datos incompletos. Las tarifas vienen del PDF; fórmulas, impuestos y mandatorios deben confirmarse antes de aprobación. Todo se guarda solo en este navegador.<br><span class="help"><b>(*)</b> obligatorio al aprobar; sin (*) es opcional o referencial en el borrador.</span></div></div>${workflowV2()}<div class="tabs">${[['general','Información general'],['services','Servicios y cálculos'],['surcharges','Recargos'],['document','Documento'],['providers','Validación operativa'],['history','Historial']].map(([id,t])=>btn(t,'tab',tab===id?'active':'',`data-tab="${id}"`)).join('')}</div>${({general:general,services:servicesFixed,surcharges:surcharges,document:documentView,providers:providers,history:timeline}[tab]||general)()}${tab!=='document'?`<div class="footerbar"><span class="muted">${pda.template?esc(pda.template):'Sin plantilla aplicada'}<br><small>Una edición posterior invalida la aprobación simulada.</small></span><span class="spacer"></span>${associationV2()}${btn('Nueva PDA / TBN','new')}${btn('Revisar para aprobar','approve','primary')}</div>`:''}`;}
function listing(){ensurePdaV2();const d={...pda,source:'Propuesta'};const records=[d].filter(x=>(!filter.q||[x.id,x.vessel,x.voyage,x.client].join(' ').toLowerCase().includes(filter.q.toLowerCase()))&&(!filter.state||primaryStatusV2()===filter.state)&&(!filter.service||x.service===filter.service)&&(!filter.port||x.port===filter.port));return `${crumb('Buscar PDA')}<div class="heading"><div><div class="kicker">COMERCIAL</div><h1>Buscar PDA</h1><span class="muted">Busca, revisa y continúa tus propuestas.</span></div><span class="spacer"></span>${btn('+ Nueva PDA','new','primary')}</div><section class="card"><div class="filters"><label class="field">Código, nave, viaje o cliente<input data-filter="q" value="${esc(filter.q||'')}" placeholder="Ej. BOX ENDURANCE"></label><label class="field">Estado principal<select data-filter="state">${option('',filter.state||'','Todos')}${primaryStatesV2.map(x=>option(x,filter.state||'',x)).join('')}</select></label><label class="field">Tipo de servicio<select data-filter="service">${['','Liner','Tramp'].map(x=>option(x,filter.service||'',x||'Todos')).join('')}</select></label><label class="field">Puerto<select data-filter="port">${['','Callao','Paracas'].map(x=>option(x,filter.port||'',x||'Todos')).join('')}</select></label></div><div class="actions">${btn('Buscar','search','primary')}${btn('Limpiar','clear-search')}</div></section><div class="bar" style="margin-top:25px"><h2 style="margin:0">Resultados <span class="badge">${records.length}</span></h2><span class="spacer"></span><small>Propuestas locales · no es el listado completo de Monday/Cosmos</small></div><div class="tablewrap"><table><thead><tr><th>Código PDA</th><th>Nave</th><th>Viaje</th><th>Puerto</th><th>Cliente</th><th>Estado</th><th>Etapa</th></tr></thead><tbody>${records.map(x=>`<tr><td>${btn(esc(x.id),'open-record','linkbtn',`data-origin="Propuesta"`)}<span class="help">Propuesta</span></td><td>${esc(x.vessel||'TBN')}</td><td>${esc(x.voyage||'—')}</td><td>${esc(x.port)}</td><td class="longname">${esc(x.client||'Por definir')}</td><td><span class="badge blue">${esc(primaryStatusV2())}</span></td><td>${esc(currentStageV2())}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Sin resultados para estos filtros.</td></tr>'}</tbody></table></div>`;}

